parameters.jsCode:
// Normalizes input payload from Web Form, WhatsApp Flow, or Telegram Bot
const item = $input.item.json;
const body = item.body || item;

// 1. Normalize Phone to E.164 (+234 standard for Nigeria / international fallback)
let phone = String(body.phone || body.patient_phone || '').trim().replace(/[^0-9+]/g, '');
if (phone.startsWith('0') && phone.length === 11) {
  phone = '+234' + phone.substring(1);
} else if (!phone.startsWith('+') && phone.length >= 10) {
  phone = '+' + phone;
}

// 2. Validate Service and Patient Name
const patientName = String(body.patient_name || body.name || 'Valued Patient').trim();
const serviceId = body.service_id || body.service || null;
const doctorId = body.doctor_id || body.preferred_doctor_id || null;
const channel = (body.channel || 'web').toLowerCase();
const telegramChatId = body.telegram_chat_id || body.chat_id || null;
const preferredWindow = body.preferred_time_window || 'morning';
const notes = body.notes || body.patient_notes || '';

// 3. Preferred dates formatting (default to next 14 days if not provided)
let preferredDates = body.preferred_dates;
if (!preferredDates || !Array.isArray(preferredDates) || preferredDates.length === 0) {
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const inTwoWeeks = new Date(today);
  inTwoWeeks.setDate(inTwoWeeks.getDate() + 14);
  preferredDates = [tomorrow.toISOString().split('T')[0], inTwoWeeks.toISOString().split('T')[0]];
}

return {
  json: {
    patient_name: patientName,
    phone: phone,
    service_id: serviceId,
    preferred_doctor_id: doctorId,
    preferred_dates: preferredDates,
    preferred_time_window: preferredWindow,
    channel: channel,
    telegram_chat_id: telegramChatId,
    patient_notes: notes,
    raw_received_at: new Date().toISOString()
  }
};

